/* The GLib main loop owns the call flow; you only register callbacks. */
static gboolean on_tick(gpointer user_data) {
    return G_SOURCE_CONTINUE;                  /* framework calls it again */
}
g_timeout_add(1000, on_tick, app_state);
g_signal_connect(button, "clicked", G_CALLBACK(on_click), app_state);
g_main_loop_run(loop);                         /* never returns until quit */
